                    /* [BrtBkHim] */
                    /* [OLEOBJECTS] */
                    /* [ACTIVEXCONTROLS] */
                    /* [WEBPUBITEMS] */
                    /* [LISTPARTS] */
                    /* FRTWORKSHEET */
                    write_record(ba, "BrtEndSheet");
                    return ba.end();
